//
// glossary-ui.js: the accessible tooltips and the glossary drawer. All text comes from
// glossary.js (FA_GLOSSARY); this file only presents it. No dependencies, no network.
//
// Markup it understands (static in index.html or generated by viewer.js; new nodes are picked up
// by a MutationObserver, so viewer.js only has to emit the attributes):
//   <button type="button" class="tip" data-tip="id"></button>
//       a small info button: hover or keyboard focus shows the tooltip, a click or tap pins it
//       open (a toggletip with a link to the glossary entry). Its accessible name is filled in.
//   <button type="button" class="term" data-tip="id">text</button>
//       the same behaviour on inline text (dotted underline).
//   <any data-term="id">
//       hover shows the tooltip; if the element is focusable (or is a label whose control gets
//       focus) keyboard focus shows it too, and the control is described by it.
//   <button data-glossary-open>  opens the glossary drawer; data-glossary-open="id" opens at id.
// Esc closes the tooltip. The tooltip is positioned inside the viewport (and above the fixed
// transport bar), and its fade is disabled under prefers-reduced-motion (viewer.css).
// The tooltip node always stays a child of <body>: viewer.js re-renders readouts, legends and
// table rows, and a tooltip parked inside them would be destroyed with them. Keyboard users still
// reach the glossary link: Tab from an open info button moves into the tooltip, and Tab from the
// link moves on to the control after the trigger (Shift+Tab goes back to the trigger).

/* global FA_GLOSSARY */
"use strict";

(function () {
  const G = window.FA_GLOSSARY;
  if (!G) return;
  const ENTRIES = G.entries;
  const LINK_RE = /\[\[([a-z0-9-]+)(?:\|([^\]]+))?\]\]/g;
  const SHOW_DELAY_TERM = 350; // ms before a plain hover target shows its tooltip
  const SHOW_DELAY_TIP = 80; // ms for the explicit info buttons
  const HIDE_DELAY = 180; // grace period to move the pointer into the tooltip (WCAG 1.4.13)
  const MARGIN = 8;

  const plain = (s) => String(s || "").replace(LINK_RE, (_, id, text) => text || (ENTRIES[id] ? ENTRIES[id].term : id));
  const reduceMotion = () => window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  // ---------------------------------------------------------------------------------- tooltip
  const pop = document.createElement("div");
  pop.id = "fa-tip";
  pop.className = "tip-pop";
  pop.setAttribute("role", "tooltip");
  pop.hidden = true;
  const popTitle = document.createElement("p");
  popTitle.className = "tip-title";
  const popBody = document.createElement("p");
  popBody.className = "tip-body";
  const popTyp = document.createElement("p");
  popTyp.className = "tip-typ";
  const popMore = document.createElement("button");
  popMore.type = "button";
  popMore.className = "tip-more";
  pop.append(popTitle, popBody, popTyp, popMore);
  document.body.appendChild(pop);

  let current = null; // {trigger, id, pinned}
  let showTimer = 0;
  let hideTimer = 0;
  let restoring = false; // focus is being moved back to a trigger: do not reopen its tooltip
  // The trigger whose tooltip was dismissed with Esc while the pointer rested on it. Hover does
  // not reopen it until the pointer has really left it: when viewer.js rewrites a live readout's
  // text, Chrome re-fires pointerover on the stationary pointer, which would otherwise re-show
  // the tip and break "Esc dismisses" (WCAG 1.4.13).
  let dismissed = null;
  function pointerOutside(el, ev) {
    if (!el.isConnected) return true;
    const r = el.getBoundingClientRect();
    return ev.clientX < r.left || ev.clientX > r.right || ev.clientY < r.top || ev.clientY > r.bottom;
  }
  function refocus(node) {
    restoring = true;
    try {
      node.focus();
    } finally {
      restoring = false;
    }
  }

  function termOf(node) {
    if (!(node instanceof Element)) return null;
    const t = node.closest("[data-tip],[data-term]");
    if (!t) return null;
    const id = t.getAttribute("data-tip") || t.getAttribute("data-term");
    return ENTRIES[id] ? { el: t, id } : null;
  }

  function fill(id) {
    const e = ENTRIES[id];
    popTitle.textContent = e.term + (e.sym && e.term.indexOf(e.sym) < 0 ? " (" + e.sym + ")" : "");
    popBody.textContent = plain(e.short);
    popTyp.hidden = !e.typical;
    popTyp.textContent = e.typical ? "Typical: " + plain(e.typical) : "";
    popMore.textContent = "Glossary entry ›";
    popMore.dataset.glossaryOpen = id;
    popMore.setAttribute("aria-label", "Open the glossary at " + e.term);
  }

  function describe(trigger, on) {
    const list = (trigger.getAttribute("aria-describedby") || "").split(/\s+/).filter(Boolean).filter((x) => x !== pop.id);
    if (on) list.push(pop.id);
    if (list.length) trigger.setAttribute("aria-describedby", list.join(" "));
    else trigger.removeAttribute("aria-describedby");
  }

  // Keep the tooltip inside the viewport and above the fixed transport bar: above the trigger
  // when there is room, otherwise below; horizontally centred on it, then clamped.
  function place() {
    if (!current) return;
    const r = current.trigger.getBoundingClientRect();
    const vw = document.documentElement.clientWidth;
    const vh = window.innerHeight;
    const bar = parseFloat(getComputedStyle(document.documentElement).getPropertyValue("--transport-h")) || 0;
    const bottomLimit = vh - bar - MARGIN;
    pop.style.left = "0px";
    pop.style.top = "0px";
    const w = pop.offsetWidth;
    const h = pop.offsetHeight;
    let top = r.top - h - MARGIN;
    let side = "above";
    if (top < MARGIN) {
      top = r.bottom + MARGIN;
      side = "below";
      if (top + h > bottomLimit) top = Math.max(MARGIN, Math.min(r.top - h - MARGIN, bottomLimit - h));
    }
    const left = Math.min(Math.max(MARGIN, r.left + r.width / 2 - w / 2), Math.max(MARGIN, vw - w - MARGIN));
    pop.style.left = Math.round(left) + "px";
    pop.style.top = Math.round(top) + "px";
    pop.dataset.side = side;
  }

  function show(trigger, id, pinned) {
    clearTimeout(showTimer);
    clearTimeout(hideTimer);
    if (current && current.trigger !== trigger) hide(false);
    dismissed = null;
    fill(id);
    if (pop.parentNode !== document.body) document.body.appendChild(pop);
    current = { trigger, id, pinned: !!pinned };
    pop.setAttribute("role", pinned ? "dialog" : "tooltip");
    if (pinned) pop.setAttribute("aria-label", ENTRIES[id].term);
    else pop.removeAttribute("aria-label");
    if (trigger.matches("button[data-tip]")) trigger.setAttribute("aria-expanded", pinned ? "true" : "false");
    describe(trigger, true);
    pop.hidden = false;
    pop.classList.remove("in");
    place();
    // Next frame: fade in (CSS; no transition under prefers-reduced-motion).
    requestAnimationFrame(() => pop.classList.add("in"));
  }

  function hide(restoreFocus) {
    clearTimeout(showTimer);
    clearTimeout(hideTimer);
    if (!current) return;
    const t = current.trigger;
    const hadFocus = pop.contains(document.activeElement);
    describe(t, false);
    if (t.matches("button[data-tip]")) t.setAttribute("aria-expanded", "false");
    current = null;
    pop.hidden = true;
    pop.classList.remove("in");
    if (restoreFocus && hadFocus && t.isConnected) refocus(t);
  }

  function scheduleShow(trigger, id, delay) {
    clearTimeout(hideTimer);
    if (current && current.trigger === trigger) return;
    if (current && current.pinned) return; // a pinned tip stays until dismissed
    clearTimeout(showTimer);
    showTimer = setTimeout(() => show(trigger, id, false), delay);
  }
  function scheduleHide() {
    clearTimeout(showTimer);
    if (!current || current.pinned) return;
    clearTimeout(hideTimer);
    hideTimer = setTimeout(() => hide(false), HIDE_DELAY);
  }

  // Hover (mouse and pen only: a touch "hover" would fight the tap behaviour).
  document.addEventListener("pointerover", (ev) => {
    if (ev.pointerType === "touch") return;
    if (pop.contains(ev.target)) {
      clearTimeout(hideTimer);
      return;
    }
    const t = termOf(ev.target);
    if (!t) return;
    if (dismissed && (dismissed === t.el || dismissed.contains(t.el))) {
      if (!pointerOutside(dismissed, ev)) return;
      dismissed = null;
    }
    scheduleShow(t.el, t.id, t.el.matches("[data-tip]") ? SHOW_DELAY_TIP : SHOW_DELAY_TERM);
  });
  document.addEventListener("pointerout", (ev) => {
    if (ev.pointerType === "touch") return;
    const from = termOf(ev.target);
    const into = ev.relatedTarget;
    if (dismissed && into instanceof Node && !dismissed.contains(into) && pointerOutside(dismissed, ev)) dismissed = null;
    if (into instanceof Node && (pop.contains(into) || (from && from.el.contains(into)))) return;
    // Leaving a term that is not the open tooltip's trigger (e.g. the tip belongs to a
    // keyboard-focused control): only cancel that term's pending show.
    if (from && current && from.el !== current.trigger && !pop.contains(ev.target)) {
      clearTimeout(showTimer);
      return;
    }
    if (from || pop.contains(ev.target)) scheduleHide();
  });
  document.addEventListener("pointermove", (ev) => {
    if (dismissed && pointerOutside(dismissed, ev)) dismissed = null;
  }, { passive: true });

  // Keyboard focus: the info buttons, inline terms, and controls that carry (or whose label
  // carries) data-term.
  function focusTarget(node) {
    if (!(node instanceof Element) || pop.contains(node)) return null;
    let id = node.getAttribute("data-tip") || node.getAttribute("data-term");
    if (!id && node.labels && node.labels.length) {
      for (const l of node.labels) if (l.hasAttribute("data-term")) id = l.getAttribute("data-term");
    }
    return id && ENTRIES[id] ? { el: node, id } : null;
  }
  document.addEventListener("focusin", (ev) => {
    if (restoring) return;
    if (pop.contains(ev.target)) {
      clearTimeout(hideTimer);
      return;
    }
    const t = focusTarget(ev.target);
    if (t) {
      if (!(current && current.trigger === t.el)) show(t.el, t.id, false);
    } else if (current && !current.pinned) {
      hide(false);
    }
  });
  document.addEventListener("focusout", (ev) => {
    const to = ev.relatedTarget;
    if (!current) return;
    if (to instanceof Node && (pop.contains(to) || current.trigger.contains(to))) return;
    if (ev.target === current.trigger || pop.contains(ev.target)) {
      // Pinned tips close when focus leaves both the trigger and the tip.
      hide(false);
    }
  });

  // Click or tap on an info button or inline term toggles a pinned toggletip.
  document.addEventListener("click", (ev) => {
    const target = ev.target instanceof Element ? ev.target : null;
    if (!target) return;
    const opener = target.closest("[data-glossary-open]");
    if (opener) {
      ev.preventDefault();
      const back = current ? current.trigger : opener;
      hide(false);
      openGlossary(opener.getAttribute("data-glossary-open") || "", back);
      return;
    }
    const b = target.closest("button[data-tip]");
    if (b && ENTRIES[b.getAttribute("data-tip")]) {
      ev.preventDefault();
      if (current && current.trigger === b && current.pinned) hide(false);
      else show(b, b.getAttribute("data-tip"), true);
      return;
    }
    if (current && current.pinned && !pop.contains(target)) hide(false);
  });

  // The focusable controls of the page in document order (for the Tab bridge below).
  const FOCUSABLE = 'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), summary, [tabindex]:not([tabindex="-1"])';
  function nextFocusable(after) {
    for (const n of document.querySelectorAll(FOCUSABLE)) {
      if (pop.contains(n) || n.closest("[inert], dialog:not([open])") || !n.getClientRects().length) continue;
      if (after.compareDocumentPosition(n) & Node.DOCUMENT_POSITION_FOLLOWING && !after.contains(n)) return n;
    }
    return null;
  }

  document.addEventListener("keydown", (ev) => {
    if (ev.key === "Escape" && current) {
      ev.preventDefault();
      ev.stopPropagation();
      const t = current.trigger;
      hide(true);
      dismissed = t;
      return;
    }
    if (ev.key !== "Tab" || !current || pop.hidden || ev.altKey || ev.ctrlKey || ev.metaKey) return;
    const a = document.activeElement;
    if (a === current.trigger && !ev.shiftKey && current.trigger.matches("button[data-tip]")) {
      ev.preventDefault();
      popMore.focus();
    } else if (a === popMore) {
      ev.preventDefault();
      const t = current.trigger;
      if (ev.shiftKey) {
        refocus(t);
      } else {
        const n = nextFocusable(t);
        hide(false);
        if (n) n.focus();
        else refocus(t);
      }
    }
  });
  // Follow the trigger when the page or a scroll container moves (focus can scroll the page).
  let placeQueued = false;
  const queuePlace = () => {
    if (!current || placeQueued) return;
    placeQueued = true;
    requestAnimationFrame(() => {
      placeQueued = false;
      place();
    });
  };
  window.addEventListener("resize", queuePlace);
  window.addEventListener("scroll", queuePlace, { passive: true, capture: true });

  // Accessible names for the info buttons and the term hooks of new nodes (static and dynamic).
  function decorate(rootNode) {
    const nodes = rootNode.querySelectorAll ? rootNode.querySelectorAll("button.tip[data-tip]") : [];
    for (const b of nodes) {
      if (b.dataset.tipReady) continue;
      const e = ENTRIES[b.getAttribute("data-tip")];
      if (!e) continue;
      b.dataset.tipReady = "1";
      if (!b.hasAttribute("aria-label")) b.setAttribute("aria-label", "About: " + e.term);
      b.setAttribute("aria-expanded", "false");
      if (!b.textContent) b.textContent = "i";
    }
  }
  decorate(document);
  new MutationObserver((list) => {
    for (const m of list) for (const n of m.addedNodes) if (n.nodeType === 1 && n !== pop) decorate(n);
    // A pinned or open tip whose trigger was re-rendered away (table rows, legends) closes.
    if (current && !current.trigger.isConnected) hide(false);
    if (!pop.isConnected) document.body.appendChild(pop);
  }).observe(document.body, { childList: true, subtree: true });

  // ---------------------------------------------------------------------------------- glossary
  const dlg = document.getElementById("glossary");
  const listEl = document.getElementById("gloss-list");
  const search = document.getElementById("gloss-search");
  const countEl = document.getElementById("gloss-count");
  let built = false;
  let returnFocus = null;

  function richText(parent, s) {
    let last = 0;
    String(s).replace(LINK_RE, (m, id, text, off) => {
      if (off > last) parent.appendChild(document.createTextNode(s.slice(last, off)));
      const e = ENTRIES[id];
      const a = document.createElement("a");
      a.href = "#gl-" + id;
      a.className = "gl-link";
      a.dataset.glossaryJump = id;
      a.textContent = text || (e ? e.term : id);
      parent.appendChild(a);
      last = off + m.length;
      return m;
    });
    if (last < s.length) parent.appendChild(document.createTextNode(s.slice(last)));
  }

  function buildGlossary() {
    if (built || !listEl) return;
    built = true;
    const byGroup = new Map(G.groups.map((g) => [g.id, []]));
    for (const id of Object.keys(ENTRIES)) {
      const e = ENTRIES[id];
      if (byGroup.has(e.group)) byGroup.get(e.group).push(id);
    }
    const nav = document.getElementById("gloss-nav");
    for (const g of G.groups) {
      const ids = byGroup.get(g.id).sort((a, b) => ENTRIES[a].term.localeCompare(ENTRIES[b].term, "en", { sensitivity: "base" }));
      if (!ids.length) continue;
      const sec = document.createElement("section");
      sec.className = "gl-group";
      sec.id = "glg-" + g.id;
      sec.setAttribute("aria-labelledby", "glg-h-" + g.id);
      const h = document.createElement("h3");
      h.id = "glg-h-" + g.id;
      h.textContent = g.title;
      sec.appendChild(h);
      if (nav) {
        const a = document.createElement("a");
        a.href = "#glg-" + g.id;
        a.dataset.glossaryGroup = g.id;
        a.textContent = g.title;
        nav.appendChild(a);
      }
      for (const id of ids) {
        const e = ENTRIES[id];
        const art = document.createElement("article");
        art.className = "gl-entry";
        art.id = "gl-" + id;
        art.tabIndex = -1;
        art.setAttribute("aria-labelledby", "gl-h-" + id);
        const h4 = document.createElement("h4");
        h4.id = "gl-h-" + id;
        h4.textContent = e.term;
        if (e.sym && e.term.indexOf(e.sym) < 0) {
          const sy = document.createElement("span");
          sy.className = "gl-sym";
          sy.textContent = e.sym;
          h4.append(" ", sy);
        }
        art.appendChild(h4);
        const p = document.createElement("p");
        richText(p, e.long);
        art.appendChild(p);
        if (e.typical) {
          const t = document.createElement("p");
          t.className = "gl-typ";
          t.textContent = "Typical: " + plain(e.typical);
          art.appendChild(t);
        }
        const m = document.createElement("p");
        m.className = "gl-why";
        const lead = document.createElement("strong");
        lead.textContent = "For Mercury's perihelion: ";
        m.appendChild(lead);
        richText(m, e.mercury);
        art.appendChild(m);
        if (e.see && e.see.length) {
          const see = document.createElement("p");
          see.className = "gl-see";
          see.appendChild(document.createTextNode("Related: "));
          e.see.forEach((sid, i) => {
            if (i) see.appendChild(document.createTextNode(", "));
            const a = document.createElement("a");
            a.href = "#gl-" + sid;
            a.className = "gl-link";
            a.dataset.glossaryJump = sid;
            a.textContent = ENTRIES[sid] ? ENTRIES[sid].term : sid;
            see.appendChild(a);
          });
          art.appendChild(see);
        }
        // Search text: everything readable in the entry.
        art.dataset.search = (e.term + " " + (e.sym || "") + " " + plain(e.short) + " " + plain(e.long) + " " + plain(e.typical) + " " + plain(e.mercury)).toLowerCase();
        sec.appendChild(art);
      }
      listEl.appendChild(sec);
    }
    updateCount(Object.keys(ENTRIES).length);
  }

  function updateCount(n) {
    if (countEl) countEl.textContent = n === 1 ? "1 term" : n + " terms";
  }

  function filter(q) {
    const needle = q.trim().toLowerCase();
    let n = 0;
    for (const sec of listEl.querySelectorAll(".gl-group")) {
      let any = false;
      for (const art of sec.querySelectorAll(".gl-entry")) {
        const hit = !needle || art.dataset.search.indexOf(needle) >= 0;
        art.hidden = !hit;
        if (hit) {
          any = true;
          n++;
        }
      }
      sec.hidden = !any;
    }
    updateCount(n);
  }

  function jump(id) {
    const art = document.getElementById("gl-" + id);
    if (!art) return;
    if (art.hidden) {
      search.value = "";
      filter("");
    }
    art.scrollIntoView({ block: "start", behavior: reduceMotion() ? "auto" : "smooth" });
    art.focus({ preventScroll: true });
    art.classList.remove("flash");
    void art.offsetWidth; // restart the highlight
    art.classList.add("flash");
  }

  function openGlossary(id, back) {
    if (!dlg) return;
    buildGlossary();
    returnFocus = back || document.activeElement;
    if (!dlg.open) {
      if (typeof dlg.showModal === "function") dlg.showModal();
      else dlg.setAttribute("open", "");
    }
    if (id && ENTRIES[id]) jump(id);
    else if (search) search.focus();
  }

  if (dlg) {
    dlg.addEventListener("click", (ev) => {
      const t = ev.target instanceof Element ? ev.target : null;
      if (!t) return;
      const j = t.closest("[data-glossary-jump]");
      if (j) {
        ev.preventDefault();
        jump(j.dataset.glossaryJump);
        return;
      }
      const g = t.closest("[data-glossary-group]");
      if (g) {
        ev.preventDefault();
        const sec = document.getElementById("glg-" + g.dataset.glossaryGroup);
        if (sec && !sec.hidden) sec.scrollIntoView({ block: "start", behavior: reduceMotion() ? "auto" : "smooth" });
        return;
      }
      if (t.closest("[data-glossary-close]")) {
        dlg.close();
        return;
      }
      // A click on the backdrop (outside the drawer's box) closes it.
      if (t === dlg) {
        const r = dlg.getBoundingClientRect();
        const inside = ev.clientX >= r.left && ev.clientX <= r.right && ev.clientY >= r.top && ev.clientY <= r.bottom;
        if (!inside) dlg.close();
      }
    });
    dlg.addEventListener("close", () => {
      const f = returnFocus;
      returnFocus = null;
      if (f && f.isConnected && typeof f.focus === "function") refocus(f);
    });
  }
  if (search) {
    search.addEventListener("input", () => filter(search.value));
    // Esc closes the drawer at once (a type="search" field would otherwise spend the first Esc
    // clearing itself); the filter text is kept for the next opening.
    search.addEventListener("keydown", (ev) => {
      if (ev.key === "Escape" && dlg && dlg.open) {
        ev.preventDefault();
        dlg.close();
      }
    });
  }

  window.FAGlossaryUI = { open: openGlossary, hideTip: () => hide(false) };
})();
